import pandas as pd
import numpy as np


def Div(x: pd.DataFrame, y: pd.DataFrame) -> pd.DataFrame:
    result = x / y
    return result


def Rank_Div(x: pd.DataFrame, y: pd.DataFrame) -> pd.DataFrame:
    x = x.T
    y = y.T
    rank_x = x.rank() / (len(x) + 1)
    rank_y = y.rank() / (len(y) + 1)
    return (rank_x / rank_y).T


def Rank_Mul(x: pd.DataFrame, y: pd.DataFrame) -> pd.DataFrame:
    x = x.T
    y = y.T
    rank_x = x.rank() * (len(x) + 1)
    rank_y = y.rank() * (len(y) + 1)
    return (rank_x * rank_y).T


def TS_Mean(x: pd.DataFrame, d: int) -> pd.DataFrame:
    return x.rolling(d).mean()


def TS_Return(x: pd.DataFrame, d: int) -> pd.DataFrame:
    return x.pct_change(d)


def TS_Skew(x: pd.DataFrame, d: int) -> pd.DataFrame:
    return x.rolling(window=d).skew()


def TS_Std(x: pd.DataFrame, d: int) -> pd.DataFrame:
        result = x.rolling(window=d).std()
        return result


def signal_vol_accel_extreme(Open: pd.DataFrame, Close: pd.DataFrame) -> pd.DataFrame:
    """Rank_Mul(Rank_Div(TS_Std(Close,5), Rank_Mul(TS_Std(Close,20),10)), Rank_Mul(TS_Return(Open,60),5))"""
    return Rank_Mul(Rank_Div(TS_Std(Close, 5), Rank_Mul(TS_Std(Close, 20), 10)), Rank_Mul(TS_Return(Open, 60), 5))

def signal_vol_trend_skew(Close: pd.DataFrame) -> pd.DataFrame:
    """Rank_Mul(TS_Skew(Close,120), Div(TS_Std(Close,30), TS_Mean(TS_Std(Close,20),120)))"""
    return Rank_Mul(TS_Skew(Close, 120), Div(TS_Std(Close, 30), TS_Mean(TS_Std(Close, 20), 120)))
